package main

const coreSchema = "CREATE TABLE IF NOT EXISTS agents (id BIGSERIAL PRIMARY KEY, uuid TEXT UNIQUE NOT NULL, agent_key VARCHAR(64), hostname VARCHAR(256), ip INET, os VARCHAR(128), agent_version VARCHAR(32), status VARCHAR(16) DEFAULT 'offline', traffic_enabled BOOLEAN DEFAULT false, hids_enabled BOOLEAN DEFAULT false, rasp_enabled BOOLEAN DEFAULT false, last_heartbeat TIMESTAMPTZ, config JSONB, tags TEXT[], enrolled_at TIMESTAMPTZ DEFAULT NOW()); CREATE INDEX IF NOT EXISTS idx_agents_status ON agents(status); CREATE INDEX IF NOT EXISTS idx_agents_uuid ON agents(uuid); CREATE TABLE IF NOT EXISTS events (id BIGSERIAL PRIMARY KEY, event_uid VARCHAR(160), timestamp TIMESTAMPTZ NOT NULL DEFAULT NOW(), event_type VARCHAR(32) NOT NULL DEFAULT 'unknown', source VARCHAR(64), severity VARCHAR(16), raw_data JSONB, metadata JSONB, status VARCHAR(16) DEFAULT 'new', created_at TIMESTAMPTZ DEFAULT NOW()); CREATE UNIQUE INDEX IF NOT EXISTS idx_events_uid ON events(event_uid); CREATE INDEX IF NOT EXISTS idx_events_timestamp ON events(timestamp DESC);"
